INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-07-30' FROM countries WHERE name_en = 'Portugal';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer) SELECT id, 'en', 'Certified-software & document-security regime, with a genuine B2G structured-invoice mandate — no general B2B/B2C mandate yet', 'This deep-dive page reflects publicly available technical guidance as of July 2026 and is provided for general awareness, not legal or tax advice. Portugal''s 2027 QES deadline has already shifted once via the annual State Budget process, and the same is true of the SAF-T full accounting file timeline — confirm current requirements directly with the Autoridade Tributária before building an integration.' FROM countries WHERE name_en = 'Portugal';
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Portugal';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', 'No B2B', 'mandate — yet');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Portugal';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '2026', 'B2G extends to SME/micro');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Portugal';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '2027', 'QES required for PDFs');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Portugal';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '10 yrs', 'Archive requirement');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Portugal';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', 'CIUS-PT', 'B2G structured format');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Portugal';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'B2G structured format', '[["National specification", "CIUS-PT"], ["Based on", "EN 16931 (European standard)"], ["Syntaxes", "UBL 2.1 or CEFACT CII"]]', 'CIUS-PT is Portugal''s national adaptation of the EU standard — implementations should target UBL 2.1 CIUS-PT specifically, not a generic EN 16931 build.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Portugal';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'B2B / B2C — no structured mandate', '[["Accepted formats", "Paper, PDF \u2014 no XML requirement"], ["What''s required regardless", "AT-certified software, ATCUD, QR code"]]', 'Don''t mistake "no structured-format mandate" for "no requirements" — the certified-software and document-security layer applies to every invoice regardless of format.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Portugal';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'The 2027 QES layer', '[["Applies to", "PDF invoices, B2B and B2C"], ["Provider requirement", "EU-listed qualified trust service provider"], ["Deferred from", "An original 2026 date"]]', 'This exists specifically because PDFs, unlike structured XML, can be altered after issuance unless cryptographically sealed — QES is Portugal''s answer to that gap.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 3 FROM countries WHERE name_en = 'Portugal';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'SAF-T (PT) reporting', '[["Monthly billing file", "Already required"], ["Full accounting file", "Mandatory from 2028, covering 2027"]]', 'The full accounting SAF-T file is a materially bigger scope than the monthly billing file already in force — don''t assume existing SAF-T compliance covers it automatically.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE name_en = 'Portugal';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'B2G transmission', '[["Platform", "FE-AP (eSPap-operated)"], ["Alternative", "Other AT-approved channels"]]', 'Suppliers to public bodies must connect to FE-AP or an equivalent approved channel — this is the one place in Portugal''s regime with a genuine transmission requirement.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Portugal';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'B2B / B2C transmission', '[["Mandate", "None \u2014 any exchange method is legally acceptable"], ["What still applies", "Certified software, ATCUD, QR, and (from 2027) QES for PDFs"]]', 'A genuinely different model from clearance-model peers in this tracker — there''s no tax-authority validation step before an invoice is legally issued.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Portugal';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'The universal net: certified software', '[["Applies to", "Every invoice, every business, regardless of B2G status"], ["Consequence of non-use", "Invoice is invalid, not merely non-compliant"]]', 'This is the requirement most likely to actually catch a business out — it''s easy to focus on B2G/QES timelines and overlook that certified software has been mandatory since 2010–2011.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Portugal';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '⚠️ Uncertified software invalidates the invoice, not just the software choice', NULL, NULL, 'An invoice issued on non-AT-certified software isn''t a compliance gap to fix later — it''s not considered a legally valid invoice at all.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Portugal';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📋 B2G non-compliance is a separate, distinct risk', NULL, NULL, 'Failing to issue structured CIUS-PT invoices to a public body is a distinct failure from the general certified-software requirement, and is assessed separately.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Portugal';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🔄 The 2027 QES deadline was already deferred once', NULL, NULL, 'Originally planned for 2026, the requirement moved to 2027 via the 2026 State Budget — worth tracking for further movement rather than treating the current date as certain to hold.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 3 FROM countries WHERE name_en = 'Portugal';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🗓️ SAF-T''s two obligations are easy to conflate', NULL, NULL, 'The monthly billing file (already required) and the full accounting file (due from 2028, covering 2027) are genuinely separate obligations with different scopes.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Portugal';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your invoicing software is on the AT-certified list', 'This applies to every business, regardless of size or whether B2G invoicing applies at all — using uncertified software makes an invoice invalid outright.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Portugal';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'If you supply any Portuguese public-sector body, set up CIUS-PT issuance', 'Mandatory for every company size from 1 January 2026 — connect to FE-AP or an approved alternative channel.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Portugal';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm ATCUD and QR code generation on every invoice', 'Required since 2022, regardless of B2G status or invoice format — check this is genuinely automated, not manually applied.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Portugal';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Set up monthly SAF-T (PT) billing file submission', 'Already a live requirement — don''t conflate this with the separate, larger full accounting SAF-T file due from 2028.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Portugal';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Identify an EU-listed qualified trust service provider for QES', 'Needed ahead of the 1 January 2027 deadline for PDF invoices — this is a procurement step, not a software configuration option, so start it well in advance.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 5 FROM countries WHERE name_en = 'Portugal';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Prepare for full accounting SAF-T submission by 2028', 'Covers 2027-year transactions — a materially larger scope than the monthly billing file already in force.');
INSERT INTO deep_dive_portals (country_id, url, sort_order) SELECT id, 'https://www.portaldasfinancas.gov.pt/pt/menu.action?pai=5075', 0 FROM countries WHERE name_en = 'Portugal';
INSERT INTO deep_dive_portal_translations (portal_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_portals), 'en', 'Portal das Finanças — e-Fatura (Autoridade Tributária)');
